BEGIN;
DO $test$
DECLARE a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();sid uuid;other_sid uuid:=gen_random_uuid();iid uuid:=gen_random_uuid();rid uuid:=gen_random_uuid();resume_id uuid:=gen_random_uuid();
BEGIN
 INSERT INTO auth.users(id) VALUES(a),(b);
 INSERT INTO public.profiles(id,console_user_id,email) VALUES(a,gen_random_uuid(),'phase4-a@example.invalid'),(b,gen_random_uuid(),'phase4-b@example.invalid');
 INSERT INTO public.shifts(id,employee_id) VALUES(other_sid,b);
 PERFORM set_config('request.jwt.claim.sub',a::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated;
 sid:=public.tracker_transition('CHECK_IN',rid);
 IF sid<>public.tracker_transition('CHECK_IN',rid) THEN RAISE EXCEPTION 'Check-in retry failed';END IF;
 IF (SELECT count(*) FROM public.shift_sessions)<>1 THEN RAISE EXCEPTION 'Shift view isolation failed';END IF;
 PERFORM public.tracker_record_interval(iid,sid,now()-interval '10 seconds',now(),5000,5000,3,7);
 PERFORM public.tracker_record_interval(iid,sid,now()-interval '10 seconds',now(),5000,5000,3,7);
 IF NOT EXISTS(SELECT 1 FROM public.shift_sessions WHERE id=sid AND total_worked_seconds=5 AND total_idle_seconds=5) THEN RAISE EXCEPTION 'Idempotent totals failed';END IF;
 BEGIN PERFORM public.tracker_record_interval(gen_random_uuid(),other_sid,now()-interval '10 seconds',now(),10000,0,0,0);RAISE EXCEPTION 'Foreign interval allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.tracker_transition('CHECK_OUT',gen_random_uuid(),other_sid);RAISE EXCEPTION 'Foreign checkout allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.tracker_record_interval(gen_random_uuid(),sid,now()-interval '10 seconds',now(),10000,0,0,0);RAISE EXCEPTION 'Overlap allowed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'Overlapping interval' THEN RAISE;END IF;END;
 PERFORM public.tracker_transition('TAKE_BREAK',gen_random_uuid(),sid);
 PERFORM public.tracker_transition('TAKE_BREAK',gen_random_uuid(),sid);
 IF (SELECT count(*) FROM public.shift_breaks WHERE shift_id=sid AND ended_at IS NULL)<>1 THEN RAISE EXCEPTION 'Duplicate break';END IF;
 PERFORM public.tracker_transition('RESUME',resume_id,sid);
 IF EXISTS(SELECT 1 FROM public.shift_breaks WHERE shift_id=sid AND ended_at IS NULL) THEN RAISE EXCEPTION 'Resume failed';END IF;
 PERFORM public.tracker_transition('TAKE_BREAK',gen_random_uuid(),sid);
 PERFORM public.tracker_transition('RESUME',resume_id,sid);
 IF NOT EXISTS(SELECT 1 FROM public.shift_breaks WHERE shift_id=sid AND ended_at IS NULL) THEN RAISE EXCEPTION 'Replayed resume closed a newer break';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tracker_daily_summary((now() AT TIME ZONE 'Asia/Dhaka')::date) WHERE worked_seconds=5) THEN RAISE EXCEPTION 'Daily summary failed';END IF;
 INSERT INTO public.shift_screenshots(shift_session_id,employee_id,storage_path,file_size_kb,blur_status) VALUES(sid,a,'tracker/screenshots/test.webp',10,true);
 IF NOT EXISTS(SELECT 1 FROM public.screenshots WHERE shift_id=sid AND is_blurred) THEN RAISE EXCEPTION 'Screenshot alias failed';END IF;
 BEGIN INSERT INTO public.shift_screenshots(shift_session_id,employee_id,storage_path,file_size_kb,blur_status) VALUES(other_sid,a,'tracker/screenshots/blocked.webp',10,false);RAISE EXCEPTION 'Cross-owner screenshot allowed';EXCEPTION WHEN foreign_key_violation THEN NULL;END;
 PERFORM public.tracker_transition('CHECK_OUT',gen_random_uuid(),sid);
 PERFORM public.tracker_transition('CHECK_OUT',gen_random_uuid(),sid);
 IF NOT EXISTS(SELECT 1 FROM public.shift_sessions WHERE id=sid AND status='completed' AND check_out_at IS NOT NULL) THEN RAISE EXCEPTION 'Checkout failed';END IF;
 IF has_table_privilege('authenticated','public.shift_sessions','DELETE') OR has_table_privilege('authenticated','public.shift_screenshots','DELETE') THEN RAISE EXCEPTION 'Unexpected delete access';END IF;
 RESET ROLE;
END;$test$;
ROLLBACK;
SELECT 'PASS: authenticated-role ownership isolation, idempotent check-in/interval/checkout, overlap rejection, breaks/resume, screenshot alias and blur, cross-owner shift FK, no DELETE; all fixtures rolled back' AS result;
